<script setup lang="ts">
export interface FilePaneEntry { path:string; name:string; size:number; isDir:boolean; extension?:string|null; modified?:string|number|null; icon?:string; preview?:boolean; previewDisabled?:boolean; sizeKnown?:boolean }
withDefaults(defineProps<{ entries: FilePaneEntry[]; selected: Set<string>; selectionMode?:boolean; loading?:boolean; error?:string }>(), { loading:false, error:'' })
const emit = defineEmits<{ select:[entry:FilePaneEntry,event:MouseEvent]; activate:[entry:FilePaneEntry]; preview:[entry:FilePaneEntry]; context:[entry:FilePaneEntry|null,event:MouseEvent] }>()
function bytes(value:number){if(!value)return '0 B';const units=['B','KiB','MiB','GiB','TiB'],index=Math.min(Math.floor(Math.log(value)/Math.log(1024)),4);return `${(value/1024**index).toFixed(index>1?1:0)} ${units[index]}`}
function date(value?:string|number|null){if(value===null||value===undefined||value==='')return '—';const parsed=new Date(typeof value==='number'&&value<1e12?value*1000:value);return Number.isNaN(parsed.getTime())?String(value):parsed.toLocaleString('zh-CN',{hour12:false})}
</script>
<template>
  <div class="file-pane-content">
    <div class="file-head"><span>名称</span><span>大小</span><span>修改时间</span></div>
    <div class="file-list custom-scrollbar" @contextmenu.prevent.self="emit('context',null,$event)">
      <div v-for="entry in entries" :key="entry.path" class="file-row" role="row" tabindex="0" :class="{selected:selected.has(entry.path)}" :data-path="entry.path" :data-entry-path="entry.path" @click="emit('select',entry,$event)" @dblclick="emit('activate',entry)" @contextmenu.prevent.stop="emit('context',entry,$event)" @keydown.enter.prevent="emit('activate',entry)" @keydown.space.prevent="emit('select',entry,$event as unknown as MouseEvent)">
        <span class="file-name"><input v-if="selectionMode" type="checkbox" tabindex="-1" :checked="selected.has(entry.path)" :aria-label="`选择 ${entry.name}`" @click.stop="emit('select',entry,$event)"/><i :class="entry.icon || (entry.isDir?'pi pi-folder':'pi pi-file')"/><span class="file-label" :title="entry.name"><strong>{{ entry.name }}</strong><small>{{ entry.isDir?'文件夹':(entry.extension || entry.name.split('.').pop() || '文件').toUpperCase() }}</small></span><button v-if="entry.preview" type="button" class="file-preview-trigger" data-testid="file-manager-preview" :aria-label="`预览 ${entry.name}`" title="预览" :disabled="entry.previewDisabled" @click.stop="emit('preview',entry)" @dblclick.stop @keydown.space.stop @keydown.enter.stop.prevent="emit('preview',entry)"><i class="pi pi-eye"/></button></span>
        <span :title="entry.isDir?'文件夹':bytes(entry.size)">{{ entry.isDir?'—':entry.sizeKnown===false?'大小未知':bytes(entry.size) }}</span><span :title="date(entry.modified)">{{ date(entry.modified) }}</span>
      </div>
      <div v-if="loading" class="pane-empty"><i class="pi pi-spin pi-spinner"/><span>正在读取…</span></div>
      <div v-else-if="error" class="pane-empty error"><i class="pi pi-exclamation-triangle"/><span>{{ error }}</span><slot name="error"/></div>
      <div v-else-if="!entries.length" class="pane-empty"><i class="pi pi-folder"/><span>此文件夹为空</span></div>
    </div>
  </div>
</template>
<style scoped>
.file-pane-content{display:flex;flex:1;flex-direction:column;min-width:0;min-height:0}.file-head,.file-row{box-sizing:border-box;display:grid;grid-template-columns:minmax(0,1fr) 5rem 8rem;gap:.5rem;align-items:center}.file-head{flex-shrink:0;padding:.5rem .75rem;border-bottom:1px solid var(--border-subtle);color:var(--text-muted);font-size:.62rem;font-weight:900}.file-list{flex:1;min-height:0;overflow-y:auto;overflow-x:hidden}.file-row{width:100%;padding:.52rem .75rem;border-bottom:1px solid color-mix(in srgb,var(--border-subtle) 55%,transparent);color:var(--text-muted);font-size:.64rem;text-align:left;cursor:pointer}.file-row>span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.file-row:hover{background:color-mix(in srgb,var(--dynamic-accent) 6%,transparent)}.file-row.selected{background:color-mix(in srgb,var(--dynamic-accent) 13%,transparent);outline:1px solid color-mix(in srgb,var(--dynamic-accent) 48%,transparent);outline-offset:-1px}.file-row:focus-visible{outline:2px solid var(--dynamic-accent);outline-offset:-2px}.file-name{display:flex;align-items:center;gap:.6rem}.file-name>i{width:1.2rem;flex-shrink:0;color:var(--dynamic-accent);font-size:1rem}.file-name>input{flex-shrink:0;width:14px;height:14px}.file-label{min-width:0;flex:1}.file-name strong,.file-name small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.file-name strong{color:var(--text-base);font-size:.72rem}.file-name small{margin-top:.12rem;color:var(--text-muted);font-size:.54rem}.file-preview-trigger{display:grid;place-items:center;flex-shrink:0;width:25px;height:28px;margin-left:auto;border-radius:7px;color:var(--dynamic-accent);background:color-mix(in srgb,var(--dynamic-accent) 9%,transparent)}.file-preview-trigger:hover{background:color-mix(in srgb,var(--dynamic-accent) 18%,transparent)}.file-preview-trigger:disabled{opacity:.4}.pane-empty{height:100%;min-height:90px;display:grid;place-items:center;align-content:center;gap:.6rem;padding:12px;color:var(--text-muted);font-size:.7rem;text-align:center}.pane-empty>i{font-size:1.6rem;color:var(--dynamic-accent)}.pane-empty.error{color:#ef4444;overflow-wrap:anywhere}
@media(max-width:1100px){.file-head,.file-row{grid-template-columns:minmax(0,1fr) 4rem 6rem}}@media(max-width:900px){.file-head,.file-row{grid-template-columns:minmax(0,1fr) 3.9rem}.file-head>span:last-child,.file-row>span:last-child{display:none}}@container file-pane (max-width:250px){.file-head,.file-row{grid-template-columns:minmax(0,1fr)}.file-head>span:nth-child(n+2),.file-row>span:nth-child(n+2){display:none}}
</style>
